import pytest
from inventory.pallets import pallet_count


@pytest.mark.l4("C-97b5cb90")
def test_units_fill_whole_pallets():
    """WHEN units fill whole pallets exactly, THEN returns exact quotient."""
    result = pallet_count(100, 50)
    assert result == 2


@pytest.mark.l4("C-b2a1936c")
def test_a_partly_filled_last_pallet():
    """WHEN a partly filled last pallet is needed, THEN rounds up."""
    result = pallet_count(101, 50)
    assert result == 3
